<script setup lang="ts">import { computed } from 'vue';import { useRouter } from 'vue-router';import {auth,logout} from './auth';const router=useRouter();const items=computed(()=>[{title:'Dashboard',to:'/',icon:'mdi-view-dashboard-outline',show:true},{title:'Clientes',to:'/customers',icon:'mdi-account-group-outline',show:auth.user?.role!=='CUSTOMER'},{title:'Órdenes',to:'/orders',icon:'mdi-clipboard-text-outline',show:true},{title:'Usuarios',to:'/users',icon:'mdi-account-cog-outline',show:auth.user?.role==='OWNER'}]);function exit(){logout();router.push('/login')}</script>
<template><v-app><template v-if="auth.user"><v-navigation-drawer width="252" permanent color="primary"><div class="brand"><v-icon icon="mdi-car-wrench" size="30"/><div><strong>Chevymania</strong><small>Gestión de Taller</small></div></div><v-list nav density="comfortable"><v-list-item v-for="item in items.filter(i=>i.show)" :key="item.to" :to="item.to" :prepend-icon="item.icon" :title="item.title"/></v-list><template #append><div class="user-box"><v-avatar color="accent" size="34">{{auth.user.name.slice(0,1)}}</v-avatar><div><b>{{auth.user.name}}</b><small>{{auth.user.role}} · {{auth.user.email}}</small></div><v-btn icon="mdi-logout" variant="text" size="small" @click="exit"/></div></template></v-navigation-drawer><v-app-bar elevation="0" color="surface"><v-app-bar-title><span class="overline">CHEVYMANIA / OPERACIÓN</span><br><strong>{{String($route.name||'Dashboard')}}</strong></v-app-bar-title><v-avatar color="primary" size="34">{{auth.user.name.slice(0,1)}}</v-avatar></v-app-bar><v-main><v-container fluid class="workspace"><router-view/></v-container></v-main></template><router-view v-else/></v-app></template>
<style>body{font-family:Inter,system-ui,sans-serif;color:#172033}.workspace{padding:28px 34px}.brand{padding:28px 24px;color:#fff;display:flex;gap:12px;align-items:center}.brand strong,.brand small,.user-box small{display:block}.brand small{opacity:.68;font-size:12px}.user-box{padding:18px;display:flex;align-items:center;gap:10px;color:#fff}.user-box div{min-width:0;flex:1}.user-box small{font-size:11px;opacity:.7;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.overline{font-size:10px;letter-spacing:.12em;color:#667085}</style>
